import {isFeatureEnabled} from '@github-ui/feature-flags'
import type {StepData} from '@github-ui/shared-checklist-component/Stepper'
import {Button} from '@primer/react'
import {updateSetting} from '../../helpers/settings-helper'
import {GettingStartedChecklistSettings} from '../../constants/dashboard-settings'
import type {ChecklistActions} from '../../types/checklist-types'

export const getChecklistData = (checklistActions: ChecklistActions): StepData[] => {
  return [getRepoCreationStepData(checklistActions), getCopilotStepData(), getProfileStepData()]
}

const completeChecklistItem = (item: string) => {
  updateSetting(item, true)
}

const getRepoCreationStepData = (checklistActions: ChecklistActions): StepData => {
  if (isFeatureEnabled('zero_user_dashboard_enhanced_repo_checklist_step')) {
    return {
      title: 'Create your first code project',
      description:
        'Create a project on GitHub. It’s your own space to experiment, learn, and share code with the world.',
      multipleCtaButtons: [
        {
          ctaLabel: 'Introduction to GitHub tutorial',
          href: '/new?template_owner=skills&template_name=introduction-to-github&owner=%40me&name=skills-introduction-to-github&description=My+clone+repository&visibility=public',
          autoComplete: true,
          analytics: {
            category: 'zero_user_dashboard',
            action: 'click.getting_started.create_repo.tutorial',
          },
        },
        {
          ctaLabel: 'Create a personal README.md',
          formAction: checklistActions.create_profile_readme,
          autoComplete: true,
          analytics: {
            category: 'zero_user_dashboard',
            action: 'click.getting_started.create_repo.readme',
          },
        },
        {
          ctaLabel: 'Blank repository',
          href: '/new',
          autoComplete: true,
          analytics: {
            category: 'zero_user_dashboard',
            action: 'click.getting_started.create_repo.blank',
          },
        },
      ],
    }
  } else {
    return {
      title: 'Create your first code project',
      description:
        'Create a project on GitHub. It’s your own space to experiment, learn, and share code with the world.',
      ctaLabel: 'Create project',
      href: '/new',
      autoComplete: true,
      analytics: {
        category: 'zero_user_dashboard',
        action: 'click.getting_started.create_repo',
      },
    }
  }
}

const getCopilotStepData = (): StepData => {
  return {
    title: 'Start a Copilot chat',
    description: 'Ask Copilot questions about coding or GitHub and get instant help with your first project.',
    customCta: ({onComplete, index, isActive}) => (
      <Button
        variant="primary"
        className="d-inline-flex"
        tabIndex={isActive ? 0 : -1}
        onClick={() => {
          onComplete()
          completeChecklistItem(GettingStartedChecklistSettings.TriedCopilot)
          window.location.href = '/copilot'
        }}
        data-testid={`stepper-cta-${index}`}
      >
        Start chat
      </Button>
    ),
    analytics: {
      category: 'zero_user_dashboard',
      action: 'click.getting_started.try_copilot',
    },
  }
}

const getProfileStepData = (): StepData => {
  return {
    title: 'Complete your profile',
    description:
      'Add a bio, upload an avatar, and personalize your details — building your social coding presence and connecting with others.',
    ctaLabel: 'Complete profile',
    href: '/settings/profile',
    autoComplete: true,
    analytics: {
      category: 'zero_user_dashboard',
      action: 'click.getting_started.complete_profile',
    },
  }
}
