import {Stack} from '@primer/react'
import BeginnersPlaylist from './components/BeginnerPlaylist/BeginnersPlaylist'
import {NewUserGettingStartedChecklist} from './components/NewUserGettingStartedChecklist/NewUserGettingStartedChecklist'
import {NuxDashboardDocs} from './components/NuxDashboardDocs/NuxDashboardDocs'
import {Recommendations} from './components/Recommendations/Recommendations'
import type {Dismissals} from './types/dismissals-types'
import {allModulesDismissed} from './helpers/dismissals-helper'
import {useState} from 'react'
import type {GettingStartedChecklist, ChecklistActions} from './types/checklist-types'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export interface NuxDashboardRefreshProps {
  new_user_getting_started_checklist: GettingStartedChecklist
  checklist_actions: ChecklistActions
  dismissals: Dismissals
}

export function NuxDashboardRefresh({
  new_user_getting_started_checklist,
  checklist_actions,
  dismissals,
}: NuxDashboardRefreshProps) {
  const [dismissedModules, setDismissedModules] = useState<Dismissals>({
    ...dismissals,
  })

  return allModulesDismissed(dismissedModules) ? null : isFeatureEnabled('zero_user_dashboard_alternate_layout') ? (
    <Stack direction="vertical" gap="normal" className="mb-3">
      Alternate Dashboard
    </Stack>
  ) : (
    <Stack direction="vertical" gap="normal" className="mb-3">
      <BeginnersPlaylist dismissed={dismissals.playlist_dismissed} setDismissedModules={setDismissedModules} />
      <NewUserGettingStartedChecklist
        checklist={new_user_getting_started_checklist}
        checklistActions={checklist_actions}
        dismissed={dismissals.getting_started_dismissed}
        setDismissedModules={setDismissedModules}
      />
      <NuxDashboardDocs
        heading="Start with GitHub Docs"
        dismissed={dismissals.docs_dismissed}
        setDismissedModules={setDismissedModules}
      />
      <Recommendations
        dismissed={dismissals.recommendations_dismissed}
        recommendationDismissals={{
          vscodeDismissed: dismissals.vscode_dismissed,
          desktopDismissed: dismissals.desktop_dismissed,
        }}
        setDismissedModules={setDismissedModules}
      />
    </Stack>
  )
}

try{ NuxDashboardRefresh.displayName ||= 'NuxDashboardRefresh' } catch {}